+        public async Task BatchApply(UserContractApplyReq req, List<IFormFile> formFiles = null)
+        {
+            req.Validate();
+            var referenceFileLookup = BuildReferenceFileLookup(formFiles);
+            var contractIds = req.List.Select(x => x.ContractId).ToList();
+            var contracts = await UnitWork.Find<UserContract>(x => contractIds.Contains(x.Id)).ToListAsync();
+            if (contractIds.Count != contracts.Count)
+            {
+                throw new InvalidOperationException("存在不存在的合同信息");
+            }
+
+            var existApprovals = await UnitWork.Find<UserContractApproval>(x => contractIds.Contains(x.ContractId)).ToListAsync();
+            var haveApplied = contracts.Join(existApprovals, x => new { ContractId = x.Id, x.RenewalTimes }, y => new { y.ContractId, y.RenewalTimes }, (x, y) =>
+            {
+                return (x.Id, x.RenewalTimes, x.Name);
+            }).ToList();
+            if (haveApplied.Any())
+            {
+                throw new InvalidOperationException($"以下用户的续签申请已存在：{string.Join('，', haveApplied.Select(x => $"{x.Name}[第{x.RenewalTimes + 1}次]"))}");
