+                    await Apply(flowsSheme.Id, req.SignType, item, contract, referenceFileLookup);
+                }
+                catch (Exception ex)
+                {
+                    errMsg.Add($"{contract.Name}合同续约申请失败：{ex.Message}");
+                    LogHelper.Error(ex, $"id为{item.ContractId}的合同生成审批流失败");
+                }
+            }
+            if (errMsg.Any())
+            {
+                throw new InvalidOperationException(string.Join('；', errMsg));
+            }
