+                ?? throw new ArgumentException("当前用户不属于任何部门");
+            var departManager = await UnitWork.Find<Relevance>(u => u.SecondId == org.SecondId && u.Key == Define.ORGROLE).FirstOrDefaultAsync() 
+                ?? throw new ArgumentException("当前用户所属部门没有部门主管");
+            var user = await UnitWork.Find<User>(u => u.Id == departManager.FirstId).FirstOrDefaultAsync() 
+                ?? throw new ArgumentException("部门主管不存在");
+
+            if (user.Status == 1)
