+        /// <summary>
+        /// 同步合同参考附件
+        /// </summary>
+        /// <param name="approvalId"></param>
+        /// <param name="attachments"></param>
+        /// <returns></returns>
+        private async Task SyncReferenceAttachments(long approvalId, List<UserContractReferenceAttachmentReq> attachments, Dictionary<string, Queue<IFormFile>> referenceFileLookup)
+        {
+            if (attachments == null)
+            {
+                return;
+            }
+
+            var normalizedAttachments = attachments.Where(x => x != null).ToList();
+            ValidateReferenceAttachments(normalizedAttachments);
+
+            var existingAttachments = await UnitWork.Find<UserContractAttachment>(x => x.ApprovalId == approvalId).ToListAsync();
+            var requestAttachments = normalizedAttachments.ToList();
+            var requestAttachmentKeys = requestAttachments.Select(GetReferenceAttachmentKey).ToHashSet();
+            var deleteAttachments = existingAttachments
+                .Where(x => !requestAttachmentKeys.Contains(GetReferenceAttachmentKey(x.FileName)))
+                .ToList();
+            if (deleteAttachments.Any())
+            {
+                await UnitWork.BatchDeleteAsync(deleteAttachments.ToArray());
+            }
+
+            foreach (var item in requestAttachments)
+            {
+                var attachmentKey = GetReferenceAttachmentKey(item);
+                var existingAttachment = existingAttachments
+                    .FirstOrDefault(x => GetReferenceAttachmentKey(x.FileName) == attachmentKey);
+                var uploadFile = TryDequeueReferenceFile(referenceFileLookup, item.FileName);
+                if (existingAttachment == null)
+                {
+                    if (uploadFile == null)
+                    {
+                        throw new InvalidOperationException($"未找到参考附件文件：{item.FileName}");
+                    }
+                    var addResult = await _fileApp.Add(uploadFile);
+                    await UnitWork.AddAsync<UserContractAttachment, int>(new UserContractAttachment
+                    {
+                        ApprovalId = approvalId,
+                        FileId = addResult.Id,
+                        FileName = addResult.FileName,
+                        Remark = item.Remark?.Trim(),
+                        CreateTime = DateTime.Now,
+                    });
+                    continue;
+                }
+
+                if (uploadFile != null)
+                {
+                    var addResult = await _fileApp.Add(uploadFile);
+                    existingAttachment.FileId = addResult.Id;
+                    existingAttachment.FileName = addResult.FileName;
+                    existingAttachment.CreateTime = DateTime.Now;
+                }
+                existingAttachment.Remark = item.Remark?.Trim();
+                await UnitWork.UpdateAsync(existingAttachment);
+            }
+        }
