+        /// <summary>
+        /// 获取参考附件唯一键
+        /// </summary>
+        /// <param name="fileName"></param>
+        /// <returns></returns>
+        private static string GetReferenceAttachmentKey(string fileName)
+        {
+            return fileName?.Trim() ?? string.Empty;
+        }
+
+        /// <summary>
+        /// 构建参考附件文件字典
+        /// </summary>
+        /// <param name="formFiles"></param>
+        /// <returns></returns>
+        private static Dictionary<string, Queue<IFormFile>> BuildReferenceFileLookup(List<IFormFile> formFiles)
+        {
+            var result = new Dictionary<string, Queue<IFormFile>>(StringComparer.OrdinalIgnoreCase);
+            if (formFiles == null || !formFiles.Any())
+            {
+                return result;
+            }
+
+            foreach (var file in formFiles.Where(x => x != null && x.Length > 0))
+            {
+                var key = GetReferenceAttachmentKey(file.FileName);
+                if (!result.TryGetValue(key, out var queue))
+                {
+                    queue = new Queue<IFormFile>();
+                    result[key] = queue;
+                }
+                queue.Enqueue(file);
+            }
+            return result;
+        }
+
+        /// <summary>
+        /// 获取并移除一个参考附件文件
+        /// </summary>
+        /// <param name="referenceFileLookup"></param>
+        /// <param name="fileName"></param>
+        /// <returns></returns>
+        private static IFormFile TryDequeueReferenceFile(Dictionary<string, Queue<IFormFile>> referenceFileLookup, string fileName)
+        {
+            if (referenceFileLookup == null)
+            {
+                return null;
+            }
+
+            var key = GetReferenceAttachmentKey(fileName);
+            if (!referenceFileLookup.TryGetValue(key, out var queue) || queue.Count == 0)
+            {
+                return null;
+            }
+
+            return queue.Dequeue();
+        }
