+        {
+            var loginUser = _auth.GetCurrentUser()?.User ?? throw new CommonException(Define.LoginHasExpired, Define.INVALID_TOKEN);
+            var (orgId, departManagerUserId) = await GetDepartManager(contract.UserId);
+            var processNum = await DetermineApprovalProcess(orgId);
+
+            var request = new AddFlowInstanceReq()
+            {
+                SchemeId = flowsShemeId,
+                FrmType = 2,
+                Code = DatetimeUtil.ToUnixTimestampByMilliseconds(DateTime.Now).ToString(),
+                CustomName = $"合同续签申请",
+                FrmData = "{\"process\":\"" + processNum + "\"}",
+                NodeDesignateType = Setinfo.RUNTIME_SPECIAL_USER,
+                NodeDesignates = new string[] { departManagerUserId },
+            };
+            var flowInstance = await _flowInstanceApp.CreateInstanceAndGetModelAsync(request) 
+                ?? throw new InvalidOperationException("流程实例创建失败");
+
+            var renewContractStartDate = signType switch
+            {
+                ContractSignType.Renewal => contract.CurrentContractEndDate.Value.AddDays(1),
+                ContractSignType.Resigning => req.RenewContractStartDate.Value,
+                ContractSignType.Quit => (DateTime?)null,
+                _ => throw new InvalidOperationException("不支持此续约类型"),
+            };
+            var contractApproval = new UserContractApproval()
+            {
+                SignType = signType,
+                ContractId = contract.Id,
+                ContractCompany = signType == ContractSignType.Resigning ? req.NewContractCompany : contract.ContractCompany,
+                RenewalTimes = contract.RenewalTimes,
+                RenewalContractType = req.RenewalContractType,
+                RenewalContractTerm = req.RenewalContractTerm,
+                RenewContractStartDate = renewContractStartDate,
+                RenewContractEndDate = req.RenewContractEndDate,
+                NewOrgId = req.NewOrgId,
+                NewPosition = req.NewPosition,
+                Remark = req.Remark,
+                Approval = _globalIdentityApp.GetNumId(GlobalModel.Enum.GlobalOrderType.未知),
+                FlowInstanceId = flowInstance.Id,
+                Status = ApprovalStatus.Audit,
+                CurrentProcess = flowInstance.ActivityName,
+                CurrentApproverId = flowInstance.MakerList,
+                Creator = loginUser.Id,
+                Updater = loginUser.Id,
+            };
+            await UnitWork.AddAsync<UserContractApproval, int>(contractApproval);
+            await SyncReferenceAttachments(contractApproval.Approval, req.ReferenceAttachments, referenceFileLookup);
+            await UnitWork.SaveAsync();
