+        /// <summary>
+        /// 确定审批流程
+        /// </summary>
+        /// <param name="orgId"></param>
+        /// <returns></returns>
+        private async Task<int> DetermineApprovalProcess(string orgId)
+        {
+            // 获取部门名称
+            var departmentName = await UnitWork.Find<Repository.Domain.Org>(org => org.Id == orgId).Select(org => org.Name).FirstOrDefaultAsync();
+            // 获取配置的流程部门信息
+            var processConfigurations = await UnitWork.Find<Category>(config => config.TypeId == "Employee_Registration_Department_Config").ToListAsync();
+            var departmentProcess = processConfigurations.FirstOrDefault(config => config.Description.Split(',').Contains(departmentName))
+                ?? processConfigurations.FirstOrDefault(config => config.Description == "OtherDepartment")
+                ?? throw new ArgumentException("无法确定审批流程");
+
+            return int.TryParse(departmentProcess.DtValue, out int number) ? number : throw new ArgumentException($"无法将 {departmentProcess.DtValue} 转换为整数");
+        }
