+        /// <summary>
+        /// 审批通过或拒绝
+        /// </summary>
+        /// <param name="approval"></param>
+        /// <param name="flowInstanceId"></param>
+        /// <param name="approvalType"></param>
+        /// <param name="opinion"></param>
+        /// <returns></returns>
+        /// <exception cref="CommonException"></exception>
+        /// <exception cref="InvalidOperationException"></exception>
+        private async Task Approval(UserContractApproval approval, string flowInstanceId ,ApprovalType approvalType , string opinion)
+        {
+            // 合法性校验
+            var loginUser = _auth.GetCurrentUser()?.User ?? throw new CommonException(Define.LoginHasExpired, Define.INVALID_TOKEN);
+            if (approval.Status != ApprovalStatus.Audit)
+            {
+                throw new InvalidOperationException(Define.FlowInstanceAbnormal);
+            }
+            if (approvalType != ApprovalType.Agree && approvalType != ApprovalType.Reject)
+            {
+                throw new InvalidOperationException("审批结果参数错误");
+            }
+
+            // 审批
+            var verificationReq = new VerificationReq()
+            {
+                FlowInstanceId = flowInstanceId,
+                NodeRejectType = "1",
+                VerificationFinally = approvalType == ApprovalType.Agree ? VerificationFinallyType.agree : VerificationFinallyType.reject,
+                VerificationOpinion = opinion,
+                Operator = loginUser
+            };
+            var result = await _flowInstanceApp.Verification(verificationReq);
+            var flowInstance = await UnitWork.Find<FlowInstance>(x => x.Id == flowInstanceId).FirstOrDefaultAsync();
+
+            // 考勤审批单修改状态
+            approval.Updater = loginUser.Id;
+            approval.UpdateDate = DateTime.Now;
+            approval.CurrentProcess = flowInstance.ActivityName;
+            approval.CurrentApproverId = flowInstance.MakerList;
+            if (approval.CurrentProcess == "开始")
+            {
+                approval.CurrentApproverId = string.Empty;
+            }
+            if (approvalType == ApprovalType.Reject)
+            {
+                approval.RejectedUserId = string.Join(',', approval.RejectedUserId.Split(',').Append(loginUser.Id).Distinct());
+                approval.Status = ApprovalStatus.Reject;
+            }
+            else
+            {
+                approval.ApprovedUserId = string.Join(',', approval.ApprovedUserId.Split(',').Append(loginUser.Id).Distinct());
+                approval.Status = result ? ApprovalStatus.Pass : approval.Status;
+            }
+            
+            await UnitWork.UpdateAsync(approval);
+            await UnitWork.SaveAsync();
+        }
+
+        /// <summary>
+        /// 撤回
+        /// </summary>
+        /// <param name="approvalId"></param>
+        /// <param name="opinion"></param>
+        /// <returns></returns>
+        /// <exception cref="CommonException"></exception>
+        /// <exception cref="InvalidOperationException"></exception>
+        public async Task ReCall(long approvalId, string opinion)
+        {
+            // 合法性校验
+            var loginUser = _auth.GetCurrentUser()?.User ?? throw new CommonException(Define.LoginHasExpired, Define.INVALID_TOKEN);
+            var contractApproval = await UnitWork.Find<UserContractApproval>(sr => sr.Approval == approvalId).FirstOrDefaultAsync()
+                ?? throw new InvalidOperationException($"找不到{approvalId}合同续签审批单");
+            if (contractApproval.Status != ApprovalStatus.Audit)
+            {
+                throw new InvalidOperationException($"流程已结束，无法撤回");
+            }
+            if (contractApproval.Creator != loginUser.Id)
+            {
+                throw new InvalidOperationException($"只有发起人可以撤回申请");
+            }
+
+            var flowInstance = await UnitWork.Find<FlowInstance>(fi => fi.Id == contractApproval.FlowInstanceId).FirstOrDefaultAsync()
+                ?? throw new InvalidOperationException($"找不到id为{contractApproval.FlowInstanceId}的流程");
+            if (flowInstance.IsFinish == 1)
+            {
+                throw new InvalidOperationException("流程已结束，无法审批");
+            }
+            if (flowInstance.CreateUserId != loginUser.Id)
+            {
+                throw new InvalidOperationException("只允许发起人撤回单据");
+            }
+
+            // 撤回操作
+            await _flowInstanceApp.ReCall(new RecallFlowInstanceReq { FlowInstanceId = flowInstance.Id, Description = opinion });
+
+            // 状态更新
+            var nowTime = DateTime.Now;
+            contractApproval.Updater = loginUser.Id;
+            contractApproval.UpdateDate = nowTime;
+            contractApproval.CurrentProcess = string.Empty;
+            contractApproval.CurrentApproverId = string.Empty;
+            contractApproval.Status = ApprovalStatus.Recall;
+            await UnitWork.UpdateAsync(contractApproval);
+            await UnitWork.SaveAsync();
+        }
