+        {
+            // 合法性校验
+            var loginUser = _auth.GetCurrentUser()?.User ?? throw new CommonException(Define.LoginHasExpired, Define.INVALID_TOKEN);
+            var contractApproval = await UnitWork.Find<UserContractApproval>(sr => sr.Approval == approvalId).FirstOrDefaultAsync()
+                ?? throw new InvalidOperationException($"找不到{approvalId}合同续签审批单");
+            if (contractApproval.Creator != loginUser.Id)
+            {
+                throw new InvalidOperationException($"只有发起人可以删除申请");
