+        /// <exception cref="CommonException"></exception>
+        public async Task ReApply(UserContractUpdateReq req, List<IFormFile> formFiles = null)
+        {
+            var loginUser = _auth.GetCurrentUser()?.User ?? throw new CommonException(Define.LoginHasExpired, Define.INVALID_TOKEN);
+            var referenceFileLookup = BuildReferenceFileLookup(formFiles);
+            var approval = await UnitWork.Find<UserContractApproval>(x => x.Approval == req.ApprovalId).FirstOrDefaultAsync() 
+                ?? throw new InvalidOperationException("找不到合同续签审批单");
+            var contract = await UnitWork.Find<UserContract>(x => x.Id == approval.ContractId && x.RenewalTimes == approval.RenewalTimes).FirstOrDefaultAsync()
+                ?? throw new InvalidOperationException("找不到合同信息");
+            req.Validate(approval.SignType);
+            if (approval.Creator != loginUser.Id)
+            {
+                throw new InvalidOperationException("只允许发起人重新发起");
+            }
+            if (approval.Status != ApprovalStatus.Reject && approval.Status != ApprovalStatus.Recall)
+            {
+                throw new InvalidOperationException("非驳回或撤回单据，无法重新发起");
+            }
+
+            #region 驳回或撤回重新发起
+            var (orgId, departManagerUserId) = await GetDepartManager(contract.UserId);
+            var processNum = await DetermineApprovalProcess(orgId);
+            var reStartReq = new AddFlowInstanceReq
+            {
+                FrmData = "{\"process\":\"" + processNum + "\"}",
+                Description = "重新发起",
+                NodeDesignateType = Setinfo.RUNTIME_SPECIAL_USER,
+                NodeDesignates = new string[] { departManagerUserId },
+            };
+            var flowInstance = await _flowInstanceApp.ReStartOrigin(reStartReq, approval.FlowInstanceId);
+            #endregion
+
+            // 重新发起更新数据
+            var renewContractStartDate = approval.SignType switch
+            {
+                ContractSignType.Renewal => contract.CurrentContractEndDate.Value.AddDays(1),
+                ContractSignType.Resigning => req.RenewContractStartDate.Value,
+                ContractSignType.Quit => (DateTime?)null,
+                _ => throw new InvalidOperationException("不支持此续约类型"),
+            };
+            approval.ContractCompany = approval.SignType == ContractSignType.Resigning ? req.NewContractCompany : contract.ContractCompany;
+            approval.RenewalContractType = req.RenewalContractType;
