+        /// <summary>
+        /// 校验参考附件
+        /// </summary>
+        /// <param name="attachments"></param>
+        /// <exception cref="InvalidOperationException"></exception>
+        private static void ValidateReferenceAttachments(IEnumerable<UserContractReferenceAttachmentReq> attachments)
+        {
+            var duplicateFileNames = attachments
+                .Where(x => !x.FileName.IsNullOrWhiteSpace())
+                .GroupBy(x => x.FileName.Trim(), StringComparer.OrdinalIgnoreCase)
+                .Where(x => x.Count() > 1)
+                .Select(x => x.Key)
+                .ToList();
+            if (duplicateFileNames.Any())
+            {
+                throw new InvalidOperationException($"参考附件文件名重复：{string.Join('，', duplicateFileNames)}");
+            }
+
+            if (attachments.Any(attachment => attachment.FileName.IsNullOrWhiteSpace()))
+            {
+                throw new InvalidOperationException("参考附件文件名不能为空");
+            }
+        }
