+        /// <summary>
+        /// 校验上传文件是否都已匹配到业务数据
+        /// </summary>
+        /// <param name="referenceFileLookup"></param>
+        /// <exception cref="InvalidOperationException"></exception>
+        private static void EnsureAllReferenceFilesConsumed(Dictionary<string, Queue<IFormFile>> referenceFileLookup)
+        {
+            if (referenceFileLookup == null || !referenceFileLookup.Any())
+            {
+                return;
+            }
+
+            var unMatchedFiles = referenceFileLookup.Values
+                .Where(x => x.Count > 0)
+                .SelectMany(x => x.Select(y => y.FileName))
+                .Distinct()
+                .ToList();
+            if (unMatchedFiles.Any())
+            {
+                throw new InvalidOperationException($"以下上传文件未匹配到参考附件信息：{string.Join('，', unMatchedFiles)}");
+            }
+        }
