+
+                // 更新合同信息和合同审批状态
+                contract.SignType = contractApproval.SignType;
+                contract.ContractCompany = contractApproval.SignType == ContractSignType.Resigning ? contractApproval.ContractCompany : contract.ContractCompany;
+                contract.ContractType = contractApproval.RenewalContractType;
