+        {
+            if (approval.IsAddSocial)
+            {
+                return;
+            }
+
+            // 社保转移规则：
+            // 新公司开始缴纳时间 = 新合同开始月份
+            // 原公司停缴时间 = 新合同开始月份 - 1
+            var newContractStartDate = approval.RenewContractStartDate.Value;
+            var beginPaymentTime = new DateTime(newContractStartDate.Year, newContractStartDate.Month, 1, 0, 0, 0, DateTimeKind.Unspecified);
+            
+            var socicalReq = new TransferSocialSecurityReq()
+            {
+                TransferType = TransferSocialSecurityTypeEnums.TransferLaborRelation,
