+            var contractIds = approvals.Select(x => x.ContractId).ToList();
+            var contracts = await UnitWork.Find<UserContract>(x => contractIds.Contains(x.Id)).ToListAsync();
+
+            var errMsg = new List<string>();
+            foreach (var item in req.List)
+            {
+                var approval = approvals.FirstOrDefault(x => x.Approval == item.ApprovalId);
+                var contract = contracts.FirstOrDefault(x => x.Id == approval.ContractId);
