+            }
+
+            if (approval.IsUpload)
+            {
+                throw new InvalidOperationException($"{contract.Name}已上传附件，无法修改日期");
+            }
+
+            if (approval.SignType == ContractSignType.Quit)
+            {
+                throw new InvalidOperationException($"{contract.Name}为不续签类型，无法修改日期");
+            }
+
+
+            if (req.RenewContractStartDate != null)
+            {
+                if (approval.SignType == ContractSignType.Renewal)
+                {
+                    var expectedStartDate = contract.CurrentContractEndDate.Value.AddDays(1);
+                    if (req.RenewContractStartDate != expectedStartDate)
+                    {
+                        LogHelper.Warn($"到期续签类型修改开始日期：{contract.Name}，原日期：{expectedStartDate:yyyy-MM-dd}，新日期：{req.RenewContractStartDate:yyyy-MM-dd}");
+                    }
+                }
+
+                approval.RenewContractStartDate = req.RenewContractStartDate;
+            }
+
+            if (req.RenewContractEndDate != null)
+            {
+                approval.RenewContractEndDate = req.RenewContractEndDate;
+            }
+
+            if (approval.RenewContractStartDate >= approval.RenewContractEndDate)
+            {
+                throw new InvalidOperationException($"{contract.Name}的合同开始日期必须早于结束日期");
+            }
+
+            // 验证合同类型要求
+            var hasTerms = new[] {
+                ContractTypeEnums.FixedTermContract,
+                ContractTypeEnums.NoFixedTermContract,
+                ContractTypeEnums.LabourAgreement
+            };
+
+            if (hasTerms.Contains(approval.RenewalContractType) && approval.RenewContractEndDate == null)
+            {
+                
+                throw new InvalidOperationException(
+                    $"{contract.Name}的合同类型为{EnumUtility.GetDescription(approval.RenewalContractType)}，必须设置合同结束时间");
+                
+            }
+
+            // 验证转主体必填字段
+            if (approval.SignType == ContractSignType.Resigning && approval.RenewContractStartDate == null)
+            {
+                throw new InvalidOperationException($"{contract.Name}为转主体类型，新合同开始日期不能为空");
+            }
+
+            approval.Updater = userId;
+            approval.UpdateDate = DateTime.Now;
+            await UnitWork.UpdateAsync(approval);
+            await UnitWork.SaveAsync();
+        }
