+        /// <summary>
+        /// 发送续签提醒消息
+        /// </summary>
+        /// <returns></returns>
+        public async Task SendRemindMsg()
+        {
+            var dateEnd = DateTime.Now.Date.AddDays(30);
+            var query = from uc in UnitWork.Find<UserContract>(x => x.CurrentContractEndDate != null && x.CurrentContractEndDate.Value.Date == dateEnd)
+                        join dbu in UnitWork.Find<DDBindUser>(null) on uc.UserId equals dbu.UserId
+                        join dtu in UnitWork.Find<DingTalkUserDetail>(x => x.HireStatus == HireStatus.Employed) on dbu.DDUserId equals dtu.UserId
+                        select new
+                        {
+                            uc.CurrentContractEndDate,
+                            ContractId = uc.Id,
+                            uc.RenewalTimes,
+                            dtu.Name,
+                            dtu.DepartmentCode,
+                        };
+            var userContracts = await query.ToListAsync();
+            if (!userContracts.Any())
+            {
+                return;
+            }
+            var contractApprovals = await UnitWork.Find<UserContractApproval>(x => userContracts.Select(y => y.ContractId).Contains(x.ContractId)).ToListAsync();
+            userContracts = userContracts.Where(x => !contractApprovals.Any(y => x.ContractId == y.ContractId && x.RenewalTimes == y.RenewalTimes)).ToList();
+            if (!userContracts.Any())
+            {
+                return;
+            }
+
+            var recipientList = await GetApplyDdUserId();
+            var userIds = recipientList.Config.SelectMany(y => y.UserIds).ToList();
+            var userIdToDdDict = await UnitWork.Find<DDBindUser>(x => userIds.Contains(x.UserId)).ToDictionaryAsync(x => x.UserId, x => x.DDUserId);
+            foreach (var contract in userContracts)
+            {
+                var recipients = recipientList.AllDepts.Contains(contract.DepartmentCode) 
+                    ? recipientList.Config.Where(x => x.Depts.Contains(contract.DepartmentCode)).SelectMany(x => x.UserIds).Distinct()
+                    : recipientList.Config.Where(x => x.Depts.Contains(UserContractDto.OtherDepts)).SelectMany(x => x.UserIds).Distinct();
+
+                foreach (var recipient in recipients.Where(x => x != Define.ADMINID && x != Define.BOSSBIID))
+                {
+                    var ddUserId = userIdToDdDict.GetValueOrDefault(recipient);
+                    if (ddUserId.IsNullOrEmpty())
+                    {
+                        continue;
+                    }
+                    var msg = $"用户 {contract.Name} 的合同将于 {contract.CurrentContractEndDate.Value:D} 到期，请及时处理续约事宜。";
+                    await _financeCommonApp.DDSendMsg(msg, ddUserId, "合同续约待处理", "合同续约待处理");
+                }
+            }
+        }
+
+        private async Task<UserContractDto> GetApplyDdUserId()
+        {
+            // 获取配置的流程部门信息
+            var categories = await UnitWork.Find<Category>(config => config.TypeId == "Employee_Registration_Department_Config").ToListAsync();
+            var result = new UserContractDto
+            {
+                Config = categories.Select(y => (UserIds: y.Extension.Split(','), Depts: y.Description.Split(','))).ToList(),
+            };
+            result.AllDepts = result.Config.SelectMany(x => x.Depts).Distinct().Where(x => x != UserContractDto.OtherDepts).ToList();
+            return result;
+        }
+    }
